</form>
<script>
    var diagramUrl = '<?php echo sfConfig::get('publicUrl'); ?>/templates/diagram.bpmn';
    var diagramXML = <?php echo json_encode($diagram_data ?: '') ?>;
    var diagramId = '<?php //echo json_encode($diagram->getId() ?: null) 
                        ?>';
    var taskConfigs = '<?php //echo json_encode($task_configs) 
                        ?>';
    var currentSelectedTask = null;


    const ColorPickerModule = window.ColorPickerModule;
    // Probar con diferentes nombres comunes
    const gridModule = window.gridModule ||
        window.diagramJsGrid ||
        window.DiagramJSGrid ||
        window.grid;

    console.log(ColorPickerModule);


    var bpmnModeler = new BpmnJS({
        container: '#canvas',
        additionalModules: [
            gridModule,
            ColorPickerModule
        ],
        i18n: {
            locale: 'es',
            translations: {
                'es': {
                    'Task': 'Tarea',
                    'User Task': 'Tarea de Usuario',
                    'Service Task': 'Tarea de Servicio',
                    'Script Task': 'Tarea de Script',
                    'Business Rule Task': 'Tarea de Regla de Negocio',
                    'Manual Task': 'Tarea Manual',
                    'Send Task': 'Tarea de Envío',
                    'Receive Task': 'Tarea de Recepción',
                    'Call Activity': 'Actividad de Llamada',
                    'Sub Process': 'Subproceso',
                    'Start Event': 'Evento de Inicio',
                    'End Event': 'Evento de Fin',
                    'Exclusive Gateway': 'Gateway Exclusivo',
                    'Parallel Gateway': 'Gateway Paralelo',
                    'Inclusive Gateway': 'Gateway Inclusivo',
                    'Event Based Gateway': 'Gateway Basado en Eventos',
                    'Complex Gateway': 'Gateway Complejo'
                }
            }
        }
    });

    // Ocultar elementos no deseados
    bpmnModeler.on('palette.create', function(event) {
        var palette = event.context;

        var originalGetEntries = palette.getEntries;
        palette.getEntries = function() {
            var entries = originalGetEntries.call(this);

            // Lista de elementos a ocultar
            var elementsToHide = [
                'create.script-task',
                'create.call-activity',
                'create.business-rule-task',
                'create.manual-task',
                'create.send-task',
                'create.receive-task'
            ];

            elementsToHide.forEach(function(element) {
                delete entries[element];
            });

            return entries;
        };
    });

    // Cargar diagrama
    if (diagramXML) {
        bpmnModeler.importXML(diagramXML, function(err) {
            if (err) {
                console.error('Error loading diagram:', err);
            }
        });
    }

    /**
     * Open diagram in our modeler instance.
     *
     * @param {String} bpmnXML diagram to display
     */
    async function openDiagram(bpmnXML) {
        // import diagram
        try {
            await bpmnModeler.importXML(bpmnXML);

            // access modeler components
            var canvas = bpmnModeler.get('canvas');
            var overlays = bpmnModeler.get('overlays');


            // zoom to fit full viewport
            canvas.zoom('fit-viewport');

            // attach an overlay to a node
            /*overlays.add('SCAN_OK', 'note', {
            position: {
                bottom: 0,
                right: 0
            },
            html: '<div class="diagram-note">Mixed up the labels?</div>'
            });

            // add marker
            canvas.addMarker('SCAN_OK', 'needs-discussion');*/
        } catch (err) {
            console.error('could not import BPMN 2.0 diagram', err);
        }
    }

    // load external diagram file via AJAX and open it
    jQuery.get(diagramUrl, openDiagram, 'text');

    // Evento cuando se selecciona un elemento
    bpmnModeler.on('selection.changed', function(e) {
        var element = e.newSelection[0];
        if (element && (element.type === 'bpmn:UserTask')) {
            currentSelectedTask = element;
            showTaskProperties(element);
        } else {
            currentSelectedTask = null;
            document.getElementById('task-properties').style.display = 'none';
        }
    });

    function showTaskProperties(element) {
        document.getElementById('task-properties').style.display = 'block';

        // Cargar configuración existente
        var config = taskConfigs[element.id] || {
            assignee_users: [],
            variables: []
        };

        // Seleccionar usuarios asignados
        document.querySelectorAll('.user-select').forEach(checkbox => {
            checkbox.checked = config.assignee_users.includes(checkbox.value);
        });

        // Cargar variables personalizadas
        loadVariables(config.variables);
    }

    function loadVariables(variables) {
        var container = document.getElementById('variables-container');
        container.innerHTML = '';

        variables.forEach(function(variable) {
            addVariableField(variable);
        });
    }

    function addVariableField(variable = {}) {
        var container = document.getElementById('variables-container');
        var variableId = Date.now() + Math.random(); // ID único para este campo

        var variableDiv = document.createElement('div');
        variableDiv.className = 'variable-item';
        variableDiv.dataset.variableId = variableId;
        variableDiv.innerHTML = `
        <div class="variable-row">
            <div class="variable-field">
                <input type="text" class="form-control variable-name" 
                       placeholder="Nombre de la variable" 
                       value="${variable.name || ''}">
            </div>
            <div class="variable-field">
                <select class="form-control variable-type">
                    <option value="text" ${variable.type === 'text' ? 'selected' : ''}>Texto</option>
                    <option value="number" ${variable.type === 'number' ? 'selected' : ''}>Numero</option>
                    <option value="date" ${variable.type === 'date' ? 'selected' : ''}>Fecha</option>
                    <option value="textarea" ${variable.type === 'textarea' ? 'selected' : ''}>Texto Largo</option>
                    <option value="select" ${variable.type === 'select' ? 'selected' : ''}>Lista</option>
                </select>
            </div>
            <div class="variable-field variable-options" style="display: ${variable.type === 'select' ? 'block' : 'none'};">
                <input type="text" class="form-control variable-options-input" 
                       placeholder="Options (comma separated)" 
                       value="${variable.options || ''}">
            </div>
            <div class="variable-field">
                <input type="checkbox" class="variable-required" 
                       ${variable.required ? 'checked' : ''}>
                <label>Obligatoria</label>
            </div>
            <div class="variable-field">
                <button type="button" class="btn btn-danger btn-sm remove-variable">×</button>
            </div>
        </div>
    `;
        container.appendChild(variableDiv);

        // Mostrar/Ocultar opciones según tipo
        var typeSelect = variableDiv.querySelector('.variable-type');
        var optionsDiv = variableDiv.querySelector('.variable-options');

        typeSelect.addEventListener('change', function() {
            optionsDiv.style.display = this.value === 'select' ? 'block' : 'none';
        });

        // Evento para eliminar variable
        variableDiv.querySelector('.remove-variable').addEventListener('click', function() {
            container.removeChild(variableDiv);
        });
    }

    // Evento para agregar nueva variable
    document.getElementById('add-variable').addEventListener('click', function() {
        addVariableField();
    });

    // Guardar configuración de tarea
    document.getElementById('save-task-config').addEventListener('click', function() {
        if (!currentSelectedTask) {
            //alert('Please select a task first');
            toastr.warning("Por favor seleccione una tarea primero");
            return;
        }

        // Recopilar usuarios seleccionados
        var selectedUsers = [];
        document.querySelectorAll('.user-select:checked').forEach(checkbox => {
            selectedUsers.push(checkbox.value);
        });

        // Recopilar variables personalizadas
        var variables = [];
        document.querySelectorAll('.variable-item').forEach(item => {
            var name = item.querySelector('.variable-name').value;
            var type = item.querySelector('.variable-type').value;
            var required = item.querySelector('.variable-required').checked;
            var options = item.querySelector('.variable-options-input') ? item.querySelector('.variable-options-input').value : '';

            if (name) {
                variables.push({
                    name: name,
                    type: type,
                    required: required,
                    options: options
                });
            }
        });

        // Guardar en la configuración temporal
        if (!taskConfigs[currentSelectedTask.id]) {
            taskConfigs[currentSelectedTask.id] = {
                assignee_users: [],
                variables: []
            };
        }

        taskConfigs[currentSelectedTask.id].assignee_users = selectedUsers;
        taskConfigs[currentSelectedTask.id].variables = variables;

        alert('Configuración de tarea guardada!');
    });

    // Guardar diagrama completo
    document.getElementById('save-btn').addEventListener('click', function() {
        bpmnModeler.saveXML({
            format: true
        }, function(err, xml) {
            if (err) {
                alert('Error generando XML: ' + err.message);
                return;
            }

            var name = document.getElementById('diagram-name').value;

            // Preparar datos para enviar
            var formData = new FormData();
            formData.append('name', name);
            formData.append('xml', xml);
            formData.append('task_configs', JSON.stringify(taskConfigs));
            if (diagramId) {
                formData.append('id', diagramId);
            }

            fetch('<?php echo url_for('bpmn/save') ?>', {
                    method: 'POST',
                    body: formData
                })
                .then(response => response.json())
                .then(data => {
                    if (data.success) {
                        diagramId = data.id;
                        alert('Diagrama y configuraciones guardadas exitosamente!');
                    } else {
                        alert('Error Guardando: ' + data.error);
                    }
                })
                .catch(error => {
                    alert('Error Guardando Diagrama: ' + error.message);
                });
        });
    });

    // Estilos CSS
    var style = document.createElement('style');
    style.textContent = `
