    width: 400px;
    border: 1px solid #ccc;
    padding: 15px;
    background: #f8f9fa;
    overflow-y: auto;
    border-radius: 5px;
}
.form-section {
    margin-bottom: 20px;
    padding: 15px;
    background: white;
    border-radius: 5px;
    border: 1px solid #e9ecef;
}
