    margin-bottom: 8px;
}
.user-checkbox label {
    margin-left: 5px;
    cursor: pointer;
}
.variable-item {
    margin-bottom: 10px;
    padding: 10px;
    background: #e9ecef;
    border-radius: 3px;
}
