    background: transparent; 
    color: #007cba; 
    border: 1px solid #007cba; 
}
.btn-danger { background: #dc3545; color: white; }
.btn-light { background: #f8f9fa; color: #000; border: 1px solid #ccc; }
.form-actions {
    text-align: center;
    margin-top: 20px;
    padding-top: 15px;
    border-top: 1px solid #ddd;
}
`;
    document.head.appendChild(style);
</script>